{"kind":"tool","id":"Z0ERmFdEnb4","toolName":"write_file","input":{"path":"09_WEB/2026-10-23/styles.css","instructions":"Hoja de estilos editorial para la landing de SEDAC","content":"/* SEDAC — landing 2026-10-23
   Paleta: grafito, blanco cálido, amarillo de seguridad.
   Sin dependencias externas: todo funciona en local. */

:root {
  --graphite: #141613;
  --graphite-2: #1d201b;
  --graphite-3: #2a2e27;
  --paper: #f7f4ec;
  --paper-2: #ede8dc;
  --ink: #191b17;
  --muted: #6c7066;
  --muted-dark: #a2a89b;
  --yellow: #ffc21a;
  --yellow-deep: #e0a400;
  --line: rgba(25, 27, 23, 0.14);
  --line-dark: rgba(247, 244, 236, 0.16);
  --max: 1180px;
  --pad: clamp(20px, 5vw, 64px);
  --r: 14px;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: "Helvetica Neue", "Segoe UI", Roboto, Arial, sans-serif;
  font-size: 17px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { max-width: 100%; display: block; }

h1, h2, h3 { margin: 0; line-height: 1.02; letter-spacing: -0.02em; font-weight: 700; }
p { margin: 0 0 1em; }
a { color: inherit; }

.wrap { width: 100%; max-width: var(--max); margin: 0 auto; padding: 0 var(--pad); }

/* ---------- tipografía ---------- */
.eyebrow {
  font-size: 12px; letter-spacing: 0.18em; text-transform: uppercase;
  font-weight: 700; color: var(--muted); margin: 0 0 18px;
  display: flex; align-items: center; gap: 10px;
}
.eyebrow::before {
  content: ""; width: 26px; height: 2px; background: var(--yellow); flex: none;
}
.display { font-size: clamp(2.6rem, 7vw, 5.2rem); }
.h2 { font-size: clamp(2rem, 4.4vw, 3.4rem); }
.h3 { font-size: clamp(1.25rem, 2vw, 1.6rem); }
.lead { font-size: clamp(1.05rem, 1.6vw, 1.28rem); line-height: 1.5; max-width: 34ch; }
.small { font-size: 13.5px; line-height: 1.5; }
.note { font-size: 12.5px; line-height: 1.5; color: var(--muted); }
.mono { font-variant-numeric: tabular-nums; }

/* ---------- header ---------- */
.site-header {
  position: fixed; inset: 0 0 auto 0; z-index: 60;
  background: rgba(20, 22, 19, 0.72);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid transparent;
  transition: background 0.25s ease, border-color 0.25s ease;
}
.site-header.is-scrolled { background: rgba(20, 22, 19, 0.94); border-bottom-color: var(--line-dark); }
.header-inner { display: flex; align-items: center; justify-content: space-between; height: 66px; }

.brand { display: flex; align-items: center; gap: 11px; text-decoration: none; color: var(--paper); }
.brand-mark { width: 30px; height: 30px; flex: none; }
.brand-name { font-weight: 700; letter-spacing: 0.16em; font-size: 14px; }
.brand-sub { font-size: 10.5px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--muted-dark); }

.nav { display: flex; align-items: center; gap: 30px; }
.nav a {
  color: rgba(247, 244, 236, 0.82); text-decoration: none; font-size: 14px;
  padding: 6px 0; position: relative;
}
.nav a::after {
  content: ""; position: absolute; left: 0; bottom: 0; height: 2px; width: 0;
  background: var(--yellow); transition: width 0.22s ease;
}
.nav a:hover::after, .nav a:focus-visible::after, .nav a[aria-current="true"]::after { width: 100%; }

.menu-btn {
  display: none; background: none; border: 1px solid var(--line-dark); color: var(--paper);
  width: 44px; height: 40px; border-radius: 8px; cursor: pointer; padding: 0;
  align-items: center; justify-content: center;
}
.menu-btn span { display: block; width: 18px; height: 2px; background: currentColor; position: relative; }
.menu-btn span::before, .menu-btn span::after {
  content: ""; position: absolute; left: 0; width: 18px; height: 2px; background: currentColor;
  transition: transform 0.2s ease;
}
.menu-btn span::before { top: -6px; }
.menu-btn span::after { top: 6px; }
.menu-open .menu-btn span { background: transparent; }
.menu-open .menu-btn span::before { transform: translateY(6px) rotate(45deg); }
.menu-open .menu-btn span::after { transform: translateY(-6px) rotate(-45deg); }

/* ---------- hero ---------- */
.hero {
  position: relative; background: var(--graphite); color: var(--paper);
  padding: calc(66px + clamp(52px, 8vw, 96px)) 0 clamp(56px, 7vw, 84px);
  overflow: hidden;
}
.hero::before {
  content: ""; position: absolute; inset: -20% -10% auto auto; width: 620px; height: 620px;
  background: radial-gradient(circle at center, rgba(255, 194, 26, 0.16), transparent 62%);
  pointer-events: none;
