.hero-grid { display: grid; grid-template-columns: 1.05fr 0.95fr; gap: clamp(28px, 5vw, 64px); align-items: center; position: relative; }
.hero .display { max-width: 13ch; }
.hero .display em { font-style: normal; color: var(--yellow); }
.hero-lead { margin-top: 26px; color: rgba(247, 244, 236, 0.78); font-size: clamp(1rem, 1.5vw, 1.15rem); max-width: 42ch; }
