.btn-ghost { border-color: var(--line-dark); color: var(--paper); }
.btn-ghost:hover { border-color: var(--yellow); color: var(--yellow); transform: translateY(-2px); }
.btn:focus-visible, .nav a:focus-visible, .menu-btn:focus-visible { outline: 3px solid var(--yellow); outline-offset: 3px; }

.hero-meta {
  margin-top: 42px; padding-top: 22px; border-top: 1px solid var(--line-dark);
  display: flex; flex-wrap: wrap; gap: 10px 34px; font-size: 12px; letter-spacing: 0.08em;
  text-transform: uppercase; color: var(--muted-dark);
}
.hero-meta strong { color: var(--paper); font-weight: 600; letter-spacing: 0.04em; }

.hero-figure { position: relative; }
.hero-figure svg { width: 100%; height: auto; display: block; }
.figure-tag {
  position: absolute; right: 0; bottom: -6px; font-size: 11px; letter-spacing: 0.12em;
  text-transform: uppercase; color: var(--muted-dark);
}

/* ---------- secciones ---------- */
.section { padding: clamp(64px, 9vw, 118px) 0; }
.section--tight { padding: clamp(52px, 6vw, 84px) 0; }
.section--paper2 { background: var(--paper-2); }
.section--dark { background: var(--graphite); color: var(--paper); }
.section-head { max-width: 62ch; margin-bottom: clamp(32px, 5vw, 58px); }
.section-head .h2 + p { margin-top: 18px; color: var(--muted); font-size: 1.05rem; max-width: 52ch; }
.section--dark .section-head .h2 + p { color: var(--muted-dark); }
.section--dark .eyebrow { color: var(--muted-dark); }

/* desafío: filas editoriales, no tarjetas iguales */
.challenge-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0; border-top: 1px solid var(--line); }
.challenge-item { padding: 30px 28px 34px; border-bottom: 1px solid var(--line); border-right: 1px solid var(--line); }
.challenge-item:last-child { border-right: 0; }
.challenge-item .num { font-size: 12px; letter-spacing: 0.16em; color: var(--yellow-deep); font-weight: 700; }
.challenge-item h3 { margin: 14px 0 12px; font-size: 1.2rem; letter-spacing: -0.01em; }
.challenge-item p { margin: 0; color: var(--muted); font-size: 15px; }
.challenge-foot { margin-top: 26px; display: grid; grid-template-columns: 1fr 1fr; gap: 28px; align-items: start; }
.challenge-foot .quote {
  border-left: 3px solid var(--yellow); padding-left: 18px; font-size: 1.05rem; line-height: 1.5;
}

/* propuesta */
.prop-grid { display: grid; grid-template-columns: 1.15fr 0.85fr; gap: clamp(26px, 4vw, 56px); align-items: start; }
.figure-frame { background: var(--graphite-2); border-radius: var(--r); overflow: hidden; border: 1px solid var(--line); }
.figure-frame img { width: 100%; }
.figure-cap { padding: 12px 16px; font-size: 12px; color: var(--muted); background: var(--paper); border-top: 1px solid var(--line); }
.parts { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--line); }
.parts li { display: grid; grid-template-columns: 34px 1fr; gap: 14px; padding: 18px 0; border-bottom: 1px solid var(--line); }
.parts .dot {
  width: 26px; height: 26px; border-radius: 50%; border: 1.5px solid var(--ink);
  display: grid; place-items: center; font-size: 12px; font-weight: 700; margin-top: 2px;
}
.parts h3 { font-size: 1rem; letter-spacing: -0.005em; margin-bottom: 5px; }
.parts p { margin: 0; font-size: 14px; color: var(--muted); }
.mass-strip {
  margin-top: 22px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px;
  background: var(--line); border: 1px solid var(--line); border-radius: 10px; overflow: hidden;
}
.mass-strip div { background: var(--paper); padding: 16px 14px; }
.mass-strip .v { font-size: 1.35rem; font-weight: 700; letter-spacing: -0.02em; }
.mass-strip .k { font-size: 11.5px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.1em; }

/* IMU */
.imu-head { display: grid; grid-template-columns: 1fr 0.9fr; gap: clamp(24px, 4vw, 56px); align-items: end; }
.imu-flow { margin: clamp(34px, 5vw, 56px) 0 0; display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; background: var(--line-dark); border-block: 1px solid var(--line-dark); }
.imu-step { background: var(--graphite); padding: 24px 20px 26px; position: relative; }
