.imu-plot { margin-top: 42px; display: grid; grid-template-columns: 1.2fr 0.8fr; gap: clamp(24px, 4vw, 52px); align-items: center; }
.plot-box { background: var(--graphite-2); border: 1px solid var(--line-dark); border-radius: var(--r); padding: 18px; }
