.plot-legend { display: flex; gap: 20px; flex-wrap: wrap; margin-top: 10px; font-size: 12px; color: var(--muted-dark); }
.swatch { display: inline-block; width: 18px; height: 3px; margin-right: 7px; vertical-align: middle; border-radius: 2px; }

.callout {
  border-left: 3px solid var(--yellow); padding: 4px 0 4px 18px; color: rgba(247,244,236,0.86);
