}
.callout strong { color: var(--paper); }
.limits { list-style: none; margin: 0; padding: 0; }
.limits li { position: relative; padding-left: 20px; font-size: 13.5px; color: var(--muted-dark); margin-bottom: 9px; line-height: 1.45; }
.limits li::before { content: "—"; position: absolute; left: 0; color: var(--yellow); }

/* validación: línea de etapas */
.track { display: grid; grid-template-columns: repeat(4, 1fr); gap: 22px; position: relative; margin-top: 8px; }
.track::before { content: ""; position: absolute; top: 15px; left: 4px; right: 4px; height: 1px; background: var(--line); }
.track::after { content: ""; position: absolute; top: 15px; left: 4px; width: 24%; height: 1px; background: var(--yellow); }
.stage { position: relative; padding-top: 42px; }
.stage .node {
  position: absolute; top: 6px; left: 0; width: 19px; height: 19px; border-radius: 50%;
  background: var(--paper); border: 2px solid var(--muted); box-sizing: border-box;
}
.stage.is-done .node { background: var(--yellow); border-color: var(--yellow); }
.stage.is-next .node { border-color: var(--ink); background: var(--paper); box-shadow: 0 0 0 4px rgba(255,194,26,0.28); }
.stage .state { font-size: 11px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--muted); }
.stage.is-done .state { color: var(--yellow-deep); }
.stage h3 { font-size: 1.05rem; margin: 8px 0 8px; }
.stage p { font-size: 14px; color: var(--muted); margin: 0; }

/* cierre */
.close-grid { display: grid; grid-template-columns: 1.1fr 0.9fr; gap: clamp(28px, 5vw, 64px); align-items: center; }
.close-list { list-style: none; padding: 0; margin: 0; }
.close-list li { border-top: 1px solid var(--line-dark); padding: 14px 0; display: flex; justify-content: space-between; gap: 18px; font-size: 14px; color: var(--muted-dark); }
.close-list li strong { color: var(--paper); font-weight: 600; }

footer { background: var(--graphite-2); color: var(--muted-dark); padding: 30px 0 34px; border-top: 1px solid var(--line-dark); }
.foot-inner { display: flex; flex-wrap: wrap; gap: 14px 28px; justify-content: space-between; align-items: center; font-size: 12.5px; }

/* ---------- revelado ---------- */
.reveal { opacity: 0; transform: translateY(18px); transition: opacity 0.6s ease, transform 0.6s ease; }
