  .challenge-item:last-child { border-bottom: 0; }
  .track { grid-template-columns: 1fr 1fr; row-gap: 34px; }
  .track::before, .track::after { display: none; }
  .stage { padding-top: 34px; }
  .imu-flow { grid-template-columns: 1fr 1fr; }
}
