    transition: opacity 0.2s ease, transform 0.2s ease;
  }
  .menu-open .nav { opacity: 1; transform: none; pointer-events: auto; }
  .nav a { padding: 14px 0; border-top: 1px solid var(--line-dark); font-size: 15px; }
  .menu-btn { display: inline-flex; }
  .imu-flow { grid-template-columns: 1fr; }
  .mass-strip { grid-template-columns: 1fr; }
  .challenge-foot { grid-template-columns: 1fr; }
  .hero-meta { gap: 8px 20px; }
}
